<script setup lang="ts">import {onMounted,ref} from 'vue';import {supabase} from '@/lib/supabase'
const rows=ref<any[]>([]),error=ref(''),selected=ref<any>(null),amount=ref(0),note=ref(''),busy=ref(false),show=ref(false),form=ref({name:'',phone:'',description:'',total_credit:0})
async function load(){const {data,error:e}=await supabase.from('creditors').select('*').order('created_at',{ascending:false});if(e)error.value=e.message;else rows.value=data??[]}
async function create(){busy.value=true;const total=Number(form.value.total_credit);const {error:e}=await supabase.from('creditors').insert({...form.value,total_credit:total,amount_paid:0,balance:total});if(e)error.value=e.message;else{show.value=false;form.value={name:'',phone:'',description:'',total_credit:0};await load()}busy.value=false}
async function pay(){busy.value=true;const {error:e}=await supabase.rpc('record_creditor_payment',{p_creditor_id:selected.value.id,p_amount:Number(amount.value),p_note:note.value||null});if(e)error.value=e.message;else{selected.value=null;amount.value=0;note.value='';await load()}busy.value=false}onMounted(load)
</script><template><section class="page-wrap"><div class="page-heading"><div><h1>Creditors</h1><p>Track money the business owes and record repayments.</p></div><button class="btn primary" @click="show=true">＋ Add creditor</button></div><p v-if="error" class="alert">{{error}}</p><div class="table-scroll"><table><thead><tr><th>Creditor</th><th>Phone</th><th>Total credit</th><th>Paid</th><th>Balance</th><th>Action</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.name}}</td><td>{{r.phone??'—'}}</td><td>UGX {{Number(r.total_credit).toLocaleString()}}</td><td>UGX {{Number(r.amount_paid).toLocaleString()}}</td><td>UGX {{Number(r.balance).toLocaleString()}}</td><td><button v-if="r.balance>0" class="link" @click="selected=r;amount=Number(r.balance)">Record payment</button></td></tr></tbody></table></div><div v-if="show||selected" class="modal-backdrop" @click.self="show=false;selected=null"><form v-if="show" class="modal" @submit.prevent="create"><h2>Add creditor</h2><label>Name<input v-model="form.name" class="control" required></label><label>Phone<input v-model="form.phone" class="control"></label><label>Description<input v-model="form.description" class="control"></label><label>Opening amount owed<input v-model.number="form.total_credit" type="number" min="0" step="0.01" class="control" required></label><div class="modal-actions"><button type="button" class="btn" @click="show=false">Cancel</button><button class="btn primary" :disabled="busy">Save creditor</button></div></form><form v-else class="modal" @submit.prevent="pay"><h2>Record creditor payment</h2><p>{{selected.name}} · Balance UGX {{Number(selected.balance).toLocaleString()}}</p><label>Amount<input v-model.number="amount" type="number" min="0.01" :max="selected.balance" step="0.01" class="control"></label><label>Note<input v-model="note" class="control"></label><div class="modal-actions"><button type="button" class="btn" @click="selected=null">Cancel</button><button class="btn primary" :disabled="busy||amount<=0||amount>selected.balance">Save payment</button></div></form></div></section></template>
